1	import type { ComponentType } from 'react';
2	
3	// The contribution store. It imports NOTHING — that is deliberate: discovery (slots/discover.ts)
4	// pulls in every feature's contribution file, and those files reach a slot definition, which
5	// reaches defineSlot, which reaches this file. Keeping the arrows one-way (discover -> features ->
6	// defs -> Slot -> registry) is what stops the module graph forming a cycle.
7	
8	export type Registered = {
9	  slot: string;
10	  order: number;
11	  /** Source file — the React key and the deterministic tie-break for equal `order`. */
12	  from: string;
13	  Component: ComponentType<never>;
14	};
15	
16	const contributions: Registered[] = [];
17	
18	/** Called once per contribution at startup, by slots/discover.ts. */
19	export function register(entry: Registered): void {
20	  contributions.push(entry);
21	}
22	
23	export function forSlot(id: string): Registered[] {
24	  return contributions
25	    .filter((c) => c.slot === id)
26	    .sort((a, b) => a.order - b.order || a.from.localeCompare(b.from));
27	}
